"""`KK Tears`: generated by export_nodes.py from library.blend; kept by hand from then on."""

NAME = 'KK Tears'


def build(lib):
    t = lib.new_material(NAME, props={
            'surface_render_method': 'BLENDED',
            'blend_method': 'BLEND',
            'use_transparency_overlap': False,
            'show_transparent_back': False,
            'use_backface_culling_lightprobe_volume': False,
            'preview_render_type': 'FLAT',
            'diffuse_color': (1.0, 1.0, 1.0, 1.0),
            'specular_color': (0.0, 0.0, 0.0),
            'roughness': 1.0,
            'line_color': (0.0, 0.0, 0.0, 1.0),
        })

    t.node('NodeFrame', 'FrameInfo.003', props={
        'location': (347.0, 119.5),
        'width': 200.0,
        'height': 210.5,
        'label': 'Output',
        'use_custom_color': True,
        'color': (0.6247832, 0.073067226, 0.042191483),
        'label_size': 23,
    })
    t.node('NodeFrame', 'FrameInfo.001', props={
        'location': (-155.0, 120.5),
        'width': 449.32275,
        'height': 210.5,
        'label': 'Shader',
        'use_custom_color': True,
        'color': (0.33001542, 0.4420454, 0.6247832),
        'label_size': 23,
    })
    t.node('ShaderNodeGroup', 'shader', parent='FrameInfo.001', props={
        'node_tree': lib.group('.KK Tears'),
        'location': (29.840057, -40.26935),
        'width': 389.32275,
    })
    t.node('ShaderNodeOutputMaterial', 'out', parent='FrameInfo.003', props={
        'location': (30.461395, -40.38379),
    })
    t.node('ShaderNodeTexImage', 'tex.main', props={
        'location': (-290.15994, -40.26935),
        'label': 'tex.main',
    })

    t.link('shader', 'Shader', 'out', 'Surface')
    t.link('tex.main', 'Color', 'shader', 'Main')
    return t
